function localRank(mode){const d=rankData();return[...(d[mode]||[])].sort((a,b)=>(b.score||0)-(a.score||0)||(b.totalKills||b.kills||0)-(a.totalKills||a.kills||0)||(b.duration||0)-(a.duration||0)).slice(0,20)}
