function drawSkillShieldAt(x,y,label=''){const now=performance.now(),pulse=.88+Math.sin(now*.008)*.12;ctx.save();ctx.translate(x,y);ctx.globalCompositeOperation='screen';const r=34*pulse,g=ctx.createRadialGradient(0,0,10,0,0,r+9);g.addColorStop(0,'rgba(96,165,250,.06)');g.addColorStop(.62,'rgba(59,130,246,.14)');g.addColorStop(1,'rgba(103,232,249,.34)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r+9,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(165,243,252,.92)';ctx.lineWidth=2.2;ctx.shadowColor='#22d3ee';ctx.shadowBlur=16;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='rgba(224,242,254,.95)';ctx.font='900 8px sans-serif';ctx.textAlign='center';ctx.fillText('ESCUDO DE SKILL'+(label?' · '+label:''),0,-44);ctx.restore()}
