function addDamageFx(e,amount,kind='normal'){if(!e||!Number.isFinite(amount)||amount<=0)return;const now=performance.now(),last=damageFx.length?damageFx[damageFx.length-1]:null;if(last&&last.e===e&&now-last.at<115&&last.kind===kind){last.amount+=amount;last.at=now;return}damageFx.push({e,amount,kind,at:now,x:e.x,y:e.y});if(damageFx.length>48)damageFx.splice(0,damageFx.length-48)}function drawDamageFx(){const now=performance.now();damageFx=damageFx.filter(f=>now-f.at<720);for(const f of damageFx){const age=(now-f.at)/720,p=world(f.e&&!f.e.dead?f.e.x:f.x,f.e&&!f.e.dead?f.e.y:f.y),rise=10+age*24,alpha=Math.max(0,1-age);ctx.save();ctx.globalAlpha=alpha;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=(f.kind==='flash'||f.kind==='arc'?'900 12px':'900 11px')+' -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';ctx.lineWidth=3;ctx.strokeStyle='rgba(3,7,18,.92)';ctx.fillStyle=f.kind==='flash'?'#fde047':f.kind==='arc'?'#67e8f9':f.kind==='pierce'?'#f0abfc':f.kind==='ice'?'#bae6fd':f.kind==='explosive'?'#fb923c':f.kind==='shock'?'#c4b5fd':f.kind==='meteor'?'#fb7185':'#ffffff';const txt='-'+(Math.round(f.amount*10)/10);ctx.strokeText(txt,p.x,p.y-rise);ctx.fillText(txt,p.x,p.y-rise);ctx.restore()}}function furyProfile(stage){return window.CaosCombat.furyProfile(stage)}
